"""Brute-force reference implementation of PROTOCOL.md 3.0.

Deliberately naive: lists, dicts, full scans for lag / rank_error, deepcopy
checkpoints.  Used only to validate the optimized engine.
"""
import copy
from bisect import bisect_right, insort


class RPkt:
    def __init__(self, pid, flow, length, flow_size, rank, ordinal, bank, lag):
        self.pid = pid
        self.flow = flow
        self.length = length
        self.flow_size = flow_size
        self.rank = rank
        self.ordinal = ordinal
        self.bank = bank
        self.lag = lag


class Ref:
    def __init__(self, cfg):
        self.M = cfg["banks"]
        self.L = cfg["load_balancers"]
        self.fifo_bytes = cfg["fifo_bytes"]
        self.pifo_bytes = cfg["pifo_bytes"]
        self.refill_batch = cfg["refill_batch"]
        self.sample_period = cfg["sample_period"]
        self.borders = list(cfg["borders"])
        R = len(self.borders) - 1
        self.C = [[[1 if q < (r % self.M) else 0 for r in range(R)]
                   for q in range(self.M)] for _ in range(self.L)]
        self.H = [0] * R
        self.t = 0
        self.p = 0
        self.l = 0
        self.a = 0
        self.fifos = [[] for _ in range(self.M)]   # lists of RPkt, FIFO order
        self.pifos = [[] for _ in range(self.M)]   # lists sorted by (rank,ord)
        self.live = {}                             # pid -> RPkt
        self.saves = {}
        self.svc = 0                               # count of successful pops
        pol = cfg["policy"]
        self.kind = pol["kind"]
        self.fifo_time = 0
        self.levels = dict(pol.get("levels", []))
        self.weights = dict(pol.get("weights", []))
        self.finish = {f: 0 for f in self.weights}
        self.V = 0

    # policy
    def rank_of(self, pid, flow, length, flow_size):
        if self.kind == "fifo":
            self.fifo_time += 1
            return self.fifo_time
        if self.kind == "sp":
            return self.levels[flow]
        if self.kind == "sff":
            return flow_size
        w = self.weights[flow]
        f = self.finish[flow]
        floor = f if f > self.V else self.V
        f = floor + -(-(length * 1048576) // w)
        self.finish[flow] = f
        return f

    def feedback(self, rank):
        if self.kind == "wfq" and rank > self.V:
            self.V = rank

    # queues helpers
    def fifo_used(self, q):
        return sum(p.length for p in self.fifos[q])

    def pifo_used(self, q):
        return sum(p.length for p in self.pifos[q])

    def refill(self, q):
        evicted = []
        k = min(self.refill_batch, len(self.fifos[q]))
        moved = self.fifos[q][:k]
        self.fifos[q] = self.fifos[q][k:]
        for pkt in moved:
            insort(self.pifos[q], (pkt.rank, pkt.ordinal), key=lambda t: t)
        # actually store tuples? keep objects: rebuild as list of (key,pkt)
        # simpler: keep pifos as list of RPkt sorted by (rank, ordinal)
        # (redo cleanly below)
        raise RuntimeError("unused")

    def run(self, events):
        log = []
        for i, ev in enumerate(events):
            cmd = ev[0]
            if cmd == "enqueue":
                self.do_enqueue(i, ev, log)
            elif cmd == "dequeue":
                for _ in range(ev[1]):
                    self.do_visit(i, log)
            elif cmd == "sample":
                self.do_sample(i, log)
            elif cmd == "repartition":
                self.do_repartition(i, ev[1], log)
            elif cmd == "cancel":
                self.do_cancel(i, ev[1], log)
            elif cmd == "inspect":
                self.do_inspect(i, ev[1], log)
            elif cmd == "weight":
                self.weights[ev[1]] = ev[2]
                log.append([i, "weight", ev[1], ev[2]])
            elif cmd == "save":
                self.saves[ev[1]] = self.snapshot()
                log.append([i, "save", ev[1]])
            elif cmd == "restore":
                self.restore(self.saves[ev[1]])
                log.append([i, "restore", ev[1]])
        return log

    def do_enqueue(self, i, ev, log):
        pid, flow, length, flow_size = ev[1], ev[2], ev[3], ev[4]
        rank = self.rank_of(pid, flow, length, flow_size)
        x = min(rank, self.borders[-1] - 1)
        r = bisect_right(self.borders, x) - 1
        l = self.l
        q = 0
        best = self.C[l][0][r]
        for cand in range(1, self.M):
            if self.C[l][cand][r] < best:
                best = self.C[l][cand][r]
                q = cand
        accepted = self.fifo_used(q) + length <= self.fifo_bytes
        if accepted:
            pkt = RPkt(pid, flow, length, flow_size, rank, i, q, 0)
            self.fifos[q].append(pkt)
            self.live[pid] = pkt
            self.C[l][q][r] += 1
            self.a += 1
            log.append([i, "enqueue", pid, rank, l, r, q, True])
            if self.a == self.sample_period:
                self.do_sample(i, log)
        else:
            log.append([i, "enqueue", pid, rank, l, r, q, False])
        self.l = (self.l + 1) % self.L

    def do_visit(self, i, log):
        old_t = self.t
        q = self.p
        self.t += 1
        self.p = (self.p + 1) % self.M
        evicted = []
        served = None
        if self.pifos[q]:
            served = self.pifos[q].pop(0)
            self.feedback(served.rank)
            evicted = self.refill2(q)
        else:
            evicted = self.refill2(q)
            if self.pifos[q]:
                served = self.pifos[q].pop(0)
                self.feedback(served.rank)
        if served is not None:
            rank_error = sum(1 for p in self.live.values()
                             if p is not served and p.rank < served.rank)
            lag = served.lag
            del self.live[served.pid]
            for p in self.live.values():
                if p.rank < served.rank:
                    p.lag += 1
            self.svc += 1
            log.append([i, "dequeue", old_t, q, served.pid, served.rank,
                        rank_error, lag, evicted])
        else:
            log.append([i, "dequeue", old_t, q, None, None, 0, 0, evicted])

    def refill2(self, q):
        evicted = []
        k = min(self.refill_batch, len(self.fifos[q]))
        moved = self.fifos[q][:k]
        self.fifos[q] = self.fifos[q][k:]
        for pkt in moved:
            self.pifos[q].append(pkt)
        self.pifos[q].sort(key=lambda p: (p.rank, p.ordinal))
        # longest prefix with total bytes <= pifo_bytes
        total = 0
        keep = 0
        for pkt in self.pifos[q]:
            if total + pkt.length > self.pifo_bytes:
                break
            total += pkt.length
            keep += 1
        suffix = self.pifos[q][keep:]
        self.pifos[q] = self.pifos[q][:keep]
        for pkt in reversed(suffix):   # descending (rank, ordinal)
            evicted.append(pkt.pid)
            del self.live[pkt.pid]
        return evicted

    def do_sample(self, i, log):
        R = len(self.borders) - 1
        X = [sum(self.C[l][q][r] for l in range(self.L) for q in range(self.M))
             for r in range(R)]
        for l in range(self.L):
            for r in range(R):
                m = min(self.C[l][q][r] for q in range(self.M))
                for q in range(self.M):
                    self.C[l][q][r] -= m
        self.H = [self.H[r] // 2 + X[r] for r in range(R)]
        self.a = 0
        log.append([i, "sample", X, self.H[:]])

    def do_repartition(self, i, new_borders, log):
        old = self.borders
        new = list(new_borders)

        def migrate(vec):
            out = [0] * (len(new) - 1)
            for k in range(len(old) - 1):
                m = vec[k]
                b, c = old[k], old[k + 1]
                for j in range(len(new) - 1):
                    u, v = new[j], new[j + 1]

                    def cl(x):
                        return max(0, min(x, c - b))
                    out[j] += (m * cl(v - b)) // (c - b) - (m * cl(u - b)) // (c - b)
            return out

        self.C = [[migrate(self.C[l][q]) for q in range(self.M)]
                  for l in range(self.L)]
        self.H = migrate(self.H)
        self.borders = new
        log.append([i, "repartition", len(new) - 1])

    def do_cancel(self, i, pid, log):
        pkt = self.live.get(pid)
        if pkt is None:
            log.append([i, "cancel", pid, None, None, None])
            return
        stage = "fifo"
        if pkt in self.fifos[pkt.bank]:
            self.fifos[pkt.bank].remove(pkt)
        else:
            self.pifos[pkt.bank].remove(pkt)
            stage = "pifo"
        del self.live[pid]
        log.append([i, "cancel", pid, stage, pkt.bank, pkt.lag])

    def do_inspect(self, i, pid, log):
        pkt = self.live.get(pid)
        if pkt is None:
            log.append([i, "inspect", pid, None])
            return
        stage = "fifo" if pkt in self.fifos[pkt.bank] else "pifo"
        log.append([i, "inspect", pid,
                    [pkt.rank, pkt.bank, stage, pkt.length, pkt.flow, pkt.lag]])

    def snapshot(self):
        return copy.deepcopy(self.__dict__)

    def restore(self, snap):
        self.__dict__.clear()
        self.__dict__.update(copy.deepcopy(snap))

    def certificate(self):
        queues = []
        lag_pairs = []
        for q in range(self.M):
            queues.append({
                "fifo": [p.pid for p in self.fifos[q]],
                "pifo": [p.pid for p in self.pifos[q]],
                "fifo_bytes": self.fifo_used(q),
                "pifo_bytes": self.pifo_used(q),
            })
            for p in self.fifos[q]:
                lag_pairs.append([p.pid, p.lag])
            for p in self.pifos[q]:
                lag_pairs.append([p.pid, p.lag])
        lag_pairs.sort()
        pol = {"kind": self.kind}
        if self.kind == "fifo":
            pol = {"kind": "fifo", "time": self.fifo_time}
        elif self.kind == "sp":
            pol = {"kind": "sp",
                   "levels": [[f, self.levels[f]] for f in sorted(self.levels)]}
        elif self.kind == "wfq":
            pol = {"kind": "wfq", "virtual_time": self.V,
                   "weights": [[f, self.weights[f]] for f in sorted(self.weights)],
                   "finish": [[f, self.finish[f]] for f in sorted(self.finish)]}
        return {
            "tick": self.t, "load_balancer": self.l, "service_bank": self.p,
            "sample_progress": self.a, "borders": self.borders[:],
            "counters": [lb[:] and [row[:] for row in lb] for lb in self.C],
            "history": self.H[:], "policy": pol, "queues": queues,
            "lags": lag_pairs,
        }
